#define _GNU_SOURCE

#include <dlfcn.h>
#include <stddef.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

/*
 * The audit container's PID namespace exposes /proc/self/exe but not
 * /proc/<getpid()>/exe. Lean 4.22 asks for the latter. Redirect only that
 * exact Linux executable-link shape so Lean/Lake can locate their sysroot.
 */
ssize_t readlink(const char *path, char *buffer, size_t size) {
    static ssize_t (*real_readlink)(const char *, char *, size_t);
    if (real_readlink == NULL) {
        real_readlink = dlsym(RTLD_NEXT, "readlink");
    }
    if (
        path != NULL
        && strncmp(path, "/proc/", 6) == 0
        && strcmp(path + strlen(path) - 4, "/exe") == 0
    ) {
        path = "/proc/self/exe";
    }
    return real_readlink(path, buffer, size);
}

